#!/usr/bin/env bash\nset -e\n\n# Array of Zen quotes\nquotes=(\n  "The journey of a thousand miles begins with one step."\n  "Simplicity is the ultimate sophistication."\n  "When the mind is still, the universe surrenders."\n  "Let go or be dragged."\n)\n\n# Pick a random index\nidx=$((RANDOM % ${#quotes[@]}))\nselected="${quotes[$idx]}"\n\n# Output in the format expected by GitHub Actions composite steps\n# The key must match the output name used in the action (comment)\nprintf "comment=💡 %s\n" "$selected"
